  background: transparent;
  color: var(--theme-text-secondary, #576664);
  cursor: pointer;
}
.ask-dock__mode--active {
  background: var(--theme-accent, #0f817a);
  color: var(--theme-surface-panel);
}
.ask-dock__queries {
  margin: 4px 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.ask-dock__queries li {
  font-size: 10.5px;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--theme-surface-inset, #f0f4f3);
  color: var(--theme-text-secondary, #576664);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
}
.ask-dock__ops {
  display: flex;
  flex-direction: column;
  gap: 4px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  padding: 6px 8px;
}
.ask-dock__ops ul {
