}
.ask-dock__action--prepare {
  border: 1px solid var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
}

/* §08-WC batch edit diff — one row per affected position, applied through
   the canonical save after the human confirms. */
.ask-dock__batch ul {
  padding-left: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
}
.ask-dock__batch-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 4px 10px;
  align-items: baseline;
  padding: 3px 0;
  border-top: 1px dashed var(--theme-border-subtle, #d9dfde);
}
.ask-dock__batch-row:first-child {
  border-top: 0;
}
.ask-dock__batch-where {
  font-weight: 600;
  white-space: nowrap;
}
.ask-dock__batch-ops {
  color: var(--theme-text-secondary, #576664);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ask-dock__batch-cost {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.ask-dock__batch-row.is-applied .ask-dock__batch-cost {
  color: var(--theme-accent, #0f817a);
  font-weight: 600;
}
.ask-dock__batch-row.is-failed .ask-dock__batch-cost,
.ask-dock__batch-row.is-apply_failed .ask-dock__batch-cost {
  color: var(--theme-danger, #b3261e);
}
.ask-dock__batch-row.is-unsupported {
  color: var(--theme-text-muted, #8a9493);
}
.ask-dock__batch-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  padding-top: 6px;
  font-size: 12px;
  color: var(--theme-text-secondary, #576664);
}
.ask-dock__form textarea {
  flex: 1;
  font-size: 13px;
  padding: 7px 10px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #ffffff);
  color: var(--theme-text-primary, #1f2a29);
  resize: none;
  font-family: inherit;
}

/* ---- §07-H assistant workspace ----------------------------------- */
.aiws {
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr) 300px;
  gap: 0;
  /* The workspace IS the window: bounded to the viewport minus the 46px
   * topbar and the .workspace padding (1.5rem × 2) so the transcript scrolls
   * inside — never the page, which would scroll the composer and rail off. */
  height: calc(100vh - 46px - 3rem);
  min-height: 0;
}
.aiws-rail {
  border-right: 1px solid var(--theme-border-subtle, #d9dfde);
  overflow-y: auto;
  padding: 12px;
}
.aiws-rail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
.aiws-rail__head h2 {
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--theme-text-secondary, #4b5f5c);
  margin: 0;
}
.aiws-joblist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.aiws-job {
  width: 100%;
  text-align: left;
  border: 1px solid transparent;
  background: none;
  border-radius: 8px;
  padding: 8px 10px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.aiws-job:hover {
  background: var(--theme-surface-raised, #f2f5f4);
}
.aiws-job--active {
  border-color: var(--theme-accent, #0f817a);
  background: var(--theme-accent-ghost, rgba(15, 129, 122, 0.08));
}
.aiws-job__goal {
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.aiws-job__meta {
  font-size: 11px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-state {
  display: inline-block;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--theme-surface-raised, #f2f5f4);
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-state[data-state="running"],
.aiws-state[data-state="queued"],
.aiws-state[data-state="planning"] {
  background: var(--theme-accent-ghost, rgba(15, 129, 122, 0.12));
  color: var(--theme-accent-deep);
}
.aiws-state[data-state="waiting-for-user"],
.aiws-state[data-state="waiting-for-approval"] {
  background: rgba(196, 141, 41, 0.15);
  color: var(--theme-warning);
}
.aiws-state[data-state="succeeded"] {
  background: rgba(46, 125, 79, 0.14);
  color: var(--theme-success);
}
.aiws-state[data-state="failed"],
.aiws-state[data-state="failed-retryable"] {
  background: rgba(180, 45, 45, 0.12);
  color: var(--theme-danger);
}
.aiws-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.aiws-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--theme-border-subtle, #d9dfde);
}
.aiws-head > div {
  flex: 1;
}
.aiws-head h1 {
  font-size: 15px;
  margin: 0 0 4px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-head__meta {
  font-size: 11px;
  color: var(--theme-text-secondary, #4b5f5c);
  margin: 0;
}
.aiws-transcript {
  flex: 1;
  overflow-y: auto;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.aiws-turn--user {
  align-self: flex-end;
  max-width: 72%;
  background: var(--theme-accent-ghost, rgba(15, 129, 122, 0.1));
  border-radius: 12px 12px 4px 12px;
  padding: 8px 12px;
  margin: 0;
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
  white-space: pre-wrap;
}
.aiws-turn--agent {
  max-width: 84%;
  display: flex;
  align-items: flex-start;
  gap: 9px;
}
.aiws-turn--agent .orb {
  margin-top: 1px;
}
.aiws-turn__body {
  flex: 1;
  min-width: 0;
}
.aiws-plan {
  margin: 0 0 8px;
  padding-left: 20px;
  font-size: 12px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-reply {
  margin: 0;
  font-size: 14px;
  line-height: 1.5;
  color: var(--theme-text-primary, #1f2a29);
  white-space: pre-wrap;
}
.aiws-questions {
  margin-top: 8px;
  padding: 8px 12px;
  border-left: 3px solid var(--theme-warning);
  background: rgba(196, 141, 41, 0.08);
  border-radius: 0 8px 8px 0;
}
.aiws-questions p {
  margin: 0;
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-warnings {
  margin: 8px 0 0;
  padding-left: 18px;
  font-size: 12px;
  color: var(--theme-danger);
}
.aiws-toggle {
  margin-top: 8px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-raised, #f2f5f4);
  border-radius: 999px;
  font-size: 11px;
  padding: 3px 10px;
  cursor: pointer;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-work {
  margin-top: 6px;
  font-size: 12px;
  color: var(--theme-text-secondary, #4b5f5c);
  border-left: 2px solid var(--theme-border-subtle, #d9dfde);
  padding-left: 10px;
}
.aiws-work ul {
  margin: 4px 0;
  padding-left: 16px;
}
.aiws-claims small {
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-steps {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.aiws-action {
  border: 1px solid var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
  background: none;
  border-radius: 999px;
  font-size: 11px;
  padding: 4px 12px;
  cursor: pointer;
}
.aiws-action--static {
  border-color: var(--theme-border-subtle, #d9dfde);
  color: var(--theme-text-secondary, #4b5f5c);
  cursor: default;
}
.aiws-artifacts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
.aiws-artifact {
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-panel, #fff);
  border-radius: 10px;
  padding: 8px 12px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: left;
}
.aiws-artifact:hover {
  border-color: var(--theme-accent, #0f817a);
}
.aiws-artifact strong {
  font-size: 12px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-artifact small {
  font-size: 10px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-live {
  font-size: 12px;
  color: var(--theme-accent, #0f817a);
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.aiws-hero {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 8px;
}
.aiws-hero__title {
  font-size: var(--text-title);
  font-weight: 600;
  margin: 0 0 4px;
}
.aiws-error {
  margin: 0 18px 8px;
  font-size: 12px;
  color: var(--theme-danger);
}
.aiws-composer {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  flex-wrap: wrap;
  padding: 12px 18px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
}
.aiws-composer .orb {
  align-self: center;
  flex-shrink: 0;
}
.aiws-composer select {
  font-size: 12px;
  padding: 6px 8px;
  max-width: 11rem;
  min-width: 0;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #fff);
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-composer textarea {
  flex: 1 1 10rem;
  min-width: 0;
  font-size: 13px;
  padding: 8px 10px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #fff);
  color: var(--theme-text-primary, #1f2a29);
  resize: none;
  font-family: inherit;
}
.aiws-inspector {
  border-left: 1px solid var(--theme-border-subtle, #d9dfde);
  overflow-y: auto;
  padding: 14px;
}
.aiws-artifact-detail h2 {
  font-size: 13px;
  margin: 0 0 4px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-evidence {
  font-size: 11px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-payload {
  font-size: 11px;
  background: var(--theme-surface-raised, #f2f5f4);
  border-radius: 8px;
  padding: 10px;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-word;
}
.aiws-empty {
  font-size: 13px;
  color: var(--theme-text-tertiary, #7b8a88);
  padding: 8px;
}
@media (max-width: 1100px) {
  .aiws {
    grid-template-columns: 210px minmax(0, 1fr);
  }
  .aiws-inspector {
    display: none;
  }
}

.aiws-tool {
  display: inline-block;
  margin-right: 6px;
  padding: 0 6px;
  border: 1px solid var(--line-strong, #d0d5dd);
  border-radius: 4px;
  background: var(--surface-sunken, #f2f4f7);
  color: var(--text-subtle, #667085);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10.5px;
  font-weight: 500;
}
.aiws-action .aiws-tool {
  margin-right: 0;
  margin-left: 6px;
}

/* §08 measurement — apply/decline pair + workspace metrics strip. */
.ask-dock__ops-actions {
  display: flex;
  gap: 6px;
  align-items: center;
}
.ask-dock__ops-actions .ask-dock__action {
  align-self: auto;
}
.ask-dock__action--ghost {
  background: transparent;
  color: var(--theme-text-secondary, #576664);
  border-style: dashed;
}
.aiws-metrics {
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 12px;
  background: var(--theme-surface-panel, #ffffff);
}
.aiws-metrics h2 {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--theme-text-secondary, #576664);
  margin: 0 0 8px;
  display: flex;
  gap: 8px;
  align-items: baseline;
}
.aiws-metrics h2 small {
  font-weight: 400;
  text-transform: none;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-metrics dl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 8px 12px;
  margin: 0;
}
.aiws-metrics dl > div {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.aiws-metrics dt {
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-metrics dd {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--theme-text-primary, #1f2a29);
  font-variant-numeric: tabular-nums;
}
.aiws-metrics__failure {
  margin: 8px 0 0;
  font-size: 11px;
  color: var(--theme-danger, #b3372f);
}

.aiws-head__actions {
  display: flex;
  flex-shrink: 0;
  gap: 0.5rem;
  margin-left: auto;
}

/* ——— Artifact chips in the dock ——— */
.ask-dock__artifacts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.ask-dock__artifact {
  border: 1px solid var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
  background: var(--theme-accent-soft, #e4f3f1);
  border-radius: 999px;
  font-size: 11px;
  padding: 3px 10px;
  cursor: pointer;
}

/* ——— Typed artifact rendering (workspace inspector) ——— */
.art {
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.art-message .art-field {
  display: flex;
  gap: 8px;
  margin: 0 0 4px;
  font-size: 12px;
}
.art-message .art-field span {
  color: var(--theme-text-tertiary, #7b8a88);
  min-width: 52px;
}
.art-body {
  margin: 8px 0 0;
  padding: 10px 12px;
  background: var(--theme-surface-raised, #f2f5f4);
  border-radius: 8px;
  white-space: pre-wrap;
  font-size: 12.5px;
  line-height: 1.5;
}
.art-checklist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.art-checklist li {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.art-checklist small {
  color: var(--theme-text-tertiary, #7b8a88);
}
.art-pill {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-radius: 999px;
  padding: 1px 8px;
  flex: none;
}
.art-pill[data-tone="ok"] {
  background: var(--theme-success-soft, #e3f2ea);
  color: var(--theme-success, #1e7a4c);
}
.art-pill[data-tone="bad"] {
  background: var(--theme-danger-soft, #fbe9e7);
  color: var(--theme-danger, #b3372f);
}
.art-pill[data-tone="warn"] {
  background: var(--theme-warning-soft, #fdf1e3);
  color: var(--theme-warning, #9c5306);
}
.art-totals {
  display: flex;
  gap: 14px;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  font-size: 12px;
}
.art-group {
  margin-bottom: 12px;
}
.art-group h3,
.art-group-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--theme-text-secondary, #4b5f5c);
  margin: 0 0 6px;
}
.art-count {
  color: var(--theme-text-tertiary, #7b8a88);
}
.art-lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.art-lines li {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.art-lines li small,
.art-lines li span {
  color: var(--theme-text-secondary, #4b5f5c);
}
.art-lines--numbered {
  list-style: decimal;
  padding-left: 18px;
}
.art-line-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.art-note {
  margin: 6px 0 0;
  font-size: 11.5px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.art-kv {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.art-kv-row {
  display: grid;
  grid-template-columns: minmax(90px, 140px) 1fr;
  gap: 8px;
  font-size: 12px;
  align-items: baseline;
}
.art-kv-row dt {
  color: var(--theme-text-secondary, #4b5f5c);
  text-transform: capitalize;
}
.art-kv-row dd {
  margin: 0;
}
.art-empty {
  margin: 0;
  color: var(--theme-text-tertiary, #7b8a88);
  font-size: 12px;
}

/* --- live run progress, waiting banner, artifact shelf, rail identity --- */
.aiws-progress {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 18px;
  padding: 7px 12px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  background: var(--theme-surface-panel, #fff);
}
.aiws-progress__label {
  font-size: 11.5px;
  color: var(--theme-text-secondary, #4b5f5c);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.aiws-waiting {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 18px;
  padding: 10px 14px;
  border: 1px solid var(--theme-warning, #c48d29);
  border-radius: 10px;
  background: rgba(196, 141, 41, 0.08);
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-shelf {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin: 0 18px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--theme-border-subtle, #d9dfde);
}
.aiws-shelf__label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-shelf__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-panel, #fff);
  border-radius: 999px;
  padding: 4px 12px 4px 6px;
  font-size: 12px;
  cursor: pointer;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-shelf__item:hover {
  border-color: var(--theme-accent, #0f817a);
}
.aiws-job {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.aiws-job .orb {
  margin-top: 2px;
}
.aiws-job__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  text-align: left;
}
.aiws-replay {
  display: inline-block;
  margin-left: 8px;
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 999px;
  padding: 0 8px;
}
.aiws-turn--error {
  max-width: 84%;
  display: flex;
  align-items: flex-start;
  gap: 9px;
}
.aiws-error__text {
  margin: 0;
  font-size: 13px;
  color: var(--theme-danger, #b3413a);
}
.aiws-error__text .aiws-tool {
  margin-left: 8px;
}
.aiws-step {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 12px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  background: var(--theme-surface-raised, #f2f5f4);
}
.aiws-step__ops {
  margin: 0;
  padding-left: 18px;
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-step__settled {
  font-size: 11.5px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-steps--live {
  flex-direction: column;
  align-items: stretch;
}
.aiws-warnings--rejected {
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-artifact {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
}
.aiws-artifact strong {
  font-size: 13px;
}
.aiws-artifact small {
  font-size: 11px;
  color: var(--theme-text-tertiary, #7b8a88);
}

/* --- dock continuity: replay mark, error turn, questions, meta link --- */
.ask-dock__replay {
  display: inline-block;
  margin-left: 8px;
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 999px;
  padding: 0 8px;
}
.ask-dock__errorTurn {
  margin-top: 4px;
  padding: 8px 12px;
  border-left: 3px solid var(--theme-danger, #b3413a);
  background: rgba(179, 65, 58, 0.07);
  border-radius: 0 8px 8px 0;
}
.ask-dock__errorTurn p {
  margin: 0 0 6px;
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__errorTurn code {
  margin-left: 8px;
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.ask-dock__questions {
  margin-top: 8px;
  padding: 8px 12px;
  border-left: 3px solid var(--theme-warning, #c48d29);
  background: rgba(196, 141, 41, 0.08);
  border-radius: 0 8px 8px 0;
}
.ask-dock__questions p {
  margin: 0;
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__meta-link {
  border: none;
  background: none;
  padding: 0;
  font: inherit;
  font-size: 11px;
  color: var(--theme-accent, #0f817a);
  cursor: pointer;
  text-decoration: underline;
}
.ask-dock__meta-link:hover {
  text-decoration: none;
}

/* Mobile: the dock is the customer/operator surface — full-width panel,
 * clear of the canvas inspector offset that only exists on desktop. */
@media (max-width: 640px) {
  .ask-dock,
  .ask-dock--canvas {
    right: 8px;
    bottom: 8px;
  }
  .ask-dock__panel {
    width: calc(100vw - 16px);
    max-height: 72vh;
  }
}

/* Bot welcome — the figure on first-open empty states. */
.ask-dock__welcome {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem 0.75rem 0.75rem;
  text-align: center;
}

.glass-selector {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
}
:is(.glass-selector, .glass-composer, .glass-rules, .glass-order, .glass-batch)
  button.ghost-button[type="button"] {
  border-radius: var(--r-1);
}
.glass-products {
  display: grid;
  gap: var(--space-1);
}
.glass-selector .glass-product {
  display: grid;
  gap: var(--space-1);
  text-align: left;
  padding: var(--space-2);
  border: 1px solid var(--border-default);
  border-radius: var(--r-1);
  background: var(--theme-surface-panel);
  color: var(--theme-text-primary);
  font: inherit;
  width: 100%;
}
.glass-product strong {
  font-weight: 500;
}
.glass-product small,
.glass-help {
  color: var(--theme-text-secondary);
  font-size: var(--type-dense);
}
.glass-product[aria-pressed="true"] {
  border-color: var(--theme-accent);
  background: var(--theme-accent-soft);
  border-left-width: var(--space-1);
}
.glass-product:hover:not(:disabled) {
  background: var(--theme-surface-hover);
}
.glass-product:disabled {
  cursor: not-allowed;
}
.glass-product:disabled:not([aria-pressed="true"]) {
  color: var(--theme-text-muted);
}
.glass-number {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.glass-field {
  display: grid;
  gap: var(--space-1);
  min-width: 0;
  font-size: var(--type-dense);
  margin-block: var(--space-1);
}
:is(.glass-selector, .glass-composer, .glass-rules) label.glass-field input,
:is(.glass-selector, .glass-composer, .glass-rules) label.glass-field select {
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
  min-height: var(--control-height);
  font: inherit;
  border: 1px solid var(--border-default);
  border-radius: var(--r-1);
  background: var(--theme-surface-panel);
  color: var(--theme-text-primary);
  padding: var(--space-1) var(--space-2);
}
.glass-field input[inputmode="decimal"],
.glass-field input[inputmode="numeric"] {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.glass-layer,
.glass-edit-fields {
  margin: 0;
  padding: var(--space-2);
  border: 1px solid var(--border-default);
  min-width: 0;
}
.glass-edit-fields {
  padding: 0;
  border: 0;
}
.glass-layer {
  margin-block: var(--space-2);
}
.glass-layer legend {
  font-size: var(--type-dense);
  font-weight: 500;
}
.glass-layer__fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2);
  border-bottom: 1px solid var(--theme-border-subtle);
  padding-bottom: var(--space-2);
}
.glass-check {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--type-dense);
  min-height: var(--control-height);
}
.glass-check input {
  flex: none;
}
.glass-actions {
  display: flex;
  gap: var(--space-1);
  flex-wrap: wrap;
  margin-block: var(--space-2);
}
.glass-findings {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: var(--space-1);
}
.glass-findings li {
  background: var(--theme-warning-soft);
  color: var(--state-warning-ink);
  border-left: var(--space-1) solid var(--theme-warning);
  padding: var(--space-2);
  font-size: var(--type-dense);
}
.glass-findings li[data-blocking="true"] {
  color: var(--theme-danger-ink);
  background: var(--theme-danger-soft);
  border-color: var(--theme-danger);
}
.glass-selector .glass-findings small,
.glass-composer .glass-findings small {
  display: block;
  margin-top: var(--space-1);
  font-size: var(--type-micro);
}
.glass-section {
  margin: var(--space-2) 0;
  padding: var(--space-2);
  border: 1px solid var(--border-default);
  background: var(--theme-bg-canvas);
}
.glass-section figcaption {
  font-weight: 500;
  font-size: var(--type-dense);
}
.glass-section__ends {
  display: flex;
  justify-content: space-between;
  margin-block: var(--space-2);
  font-size: var(--type-micro);
}
.glass-section svg {
  width: 100%;
  height: var(--space-7);
}
.glass-section__pane {
  fill: var(--theme-glass-tint);
  stroke: var(--theme-accent);
  stroke-width: 0.15;
}
.glass-section__chamber {
  fill: var(--theme-surface-panel);
  stroke: var(--theme-border-strong);
  stroke-width: 0.15;
}
.glass-section__pvb {
  fill: var(--theme-accent);
}
.glass-section ol {
  padding-left: var(--space-4);
  font-size: var(--type-micro);
}
.glass-composer {
  display: grid;
  grid-template-columns: 12rem minmax(0, 1fr);
  gap: var(--space-3);
  align-items: start;
}
.glass-composer > .glass-section {
  position: sticky;
  top: 0;
  margin: 0;
}
.glass-composer .glass-recipe {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2);
}
.glass-composer .glass-recipe > :not(.glass-field),
.glass-composer > :not(.glass-section):not(.glass-edit-fields) {
  grid-column: 1 / -1;
}
.glass-composer .glass-recipe > .glass-layer {
  margin: 0;
}
.glass-facts {
  display: grid;
  gap: var(--space-1);
  font-size: var(--type-dense);
}
.glass-facts > div {
  border-bottom: 1px solid var(--theme-border-subtle);
  padding-block: var(--space-1);
}
.glass-facts dt {
  color: var(--theme-text-secondary);
}
.glass-facts dd {
  margin: 0;
  overflow-wrap: anywhere;
}
.glass-selector details > summary {
  cursor: pointer;
  padding-block: var(--space-2);
  font-weight: 500;
  font-size: var(--type-dense);
}
.glass-publication {
  border-left: var(--space-1) solid var(--theme-accent);
  padding: var(--space-2);
}
.glass-bay-notice rect {
  fill: var(--theme-warning-soft);
  stroke: var(--theme-warning);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.glass-bay-notice text {
  fill: var(--state-warning-ink);
  font-family: var(--font-sans);
}
.glass-bay-notice {
  cursor: pointer;
}
.glass-bay-notice:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 2px;
}
.glass-rules {
  display: grid;
  gap: var(--space-3);
}
.glass-rules a {
  color: var(--theme-accent-ink);
  text-decoration: underline;
}
.glass-rule {
  border: 1px solid var(--border-default);
  padding: var(--space-3);
  min-width: 0;
}
.glass-rule-fields {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.glass-order {
  display: grid;
  gap: var(--space-2);
  margin-block: var(--space-3);
}
.glass-order-controls {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}
.glass-order-rows {
  padding-left: var(--space-5);
}
.glass-order-rows li {
  border-bottom: 1px solid var(--theme-border-subtle);
  padding-block: var(--space-2);
  overflow-wrap: anywhere;
}
.glass-batch {
  margin-block: var(--space-3);
  border-block: 1px solid var(--theme-border-subtle);
  padding-block: var(--space-2);
}
.glass-batch summary {
  cursor: pointer;
}
.glass-batch-choice {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-height: var(--control-height);
  font-size: var(--type-dense);
}
.glass-order-controls button,
.glass-batch button {
  min-height: var(--density-loose);
  min-width: var(--density-loose);
}
@media (max-width: 720px) {
  .glass-rule-fields {
    grid-template-columns: minmax(0, 1fr);
  }
  .glass-composer {
    grid-template-columns: minmax(0, 1fr);
  }
  .glass-composer > .glass-section {
    position: static;
  }
}

.landing {
  background: var(--theme-bg-canvas);
  color: var(--theme-fg-primary);
  min-height: 100vh;
}

.landing-top {
  align-items: center;
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  justify-content: space-between;
  padding: 0.875rem clamp(1rem, 4vw, 3rem);
  position: sticky;
  top: 0;
  background: var(--theme-bg-canvas);
  z-index: 10;
}

.landing-brand .brand {
  font-weight: 700;
  letter-spacing: 0.06em;
}

.landing-brand .brand-os {
  color: var(--theme-fg-muted);
  font-size: 0.75rem;
  margin-left: 0.35rem;
}

.landing-hero {
  display: grid;
  gap: 2rem;
  grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
  padding: clamp(2rem, 6vw, 5rem) clamp(1rem, 4vw, 3rem);
  align-items: center;
}

.landing-hero__copy h1 {
  font-size: clamp(1.9rem, 3.4vw, 3rem);
  line-height: 1.12;
  letter-spacing: -0.015em;
  margin: 0 0 1rem;
}

.landing-hero__lead {
  color: var(--theme-fg-secondary);
  font-size: 1.075rem;
  line-height: 1.55;
  margin: 0 0 1.5rem;
  max-width: 34rem;
}

.landing-hero__actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.landing-hero__note {
  align-items: center;
  color: var(--theme-fg-muted);
  display: flex;
  font-size: 0.875rem;
  gap: 0.5rem;
  margin-top: 1.75rem;
}

.landing-hero__shot {
  margin: 0;
}

.landing-hero__shot img,
.landing-section__shot img {
  border: 1px solid var(--theme-border-subtle);
  border-radius: 0.5rem;
  box-shadow: 0 18px 48px -20px rgb(15 24 30 / 0.28);
  display: block;
  height: auto;
  width: 100%;
}

.landing-hero__shot figcaption {
  color: var(--theme-fg-muted);
  font-size: 0.8rem;
  margin-top: 0.5rem;
  text-align: center;
}

.landing-sections {
  display: grid;
  gap: clamp(2.5rem, 6vw, 4.5rem);
  padding: 0 clamp(1rem, 4vw, 3rem) clamp(2.5rem, 6vw, 4.5rem);
}

.landing-section {
  align-items: center;
  display: grid;
  gap: clamp(1.25rem, 3vw, 2.5rem);
  grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
}

.landing-section--flip .landing-section__shot {
  order: 2;
}

.landing-section--flip .landing-section__copy {
  order: 1;
}

.landing-section__shot {
  margin: 0;
}

.landing-section__copy h2 {
  font-size: 1.5rem;
  margin: 0 0 0.75rem;
}

.landing-section__copy p {
  color: var(--theme-fg-secondary);
  line-height: 1.6;
  margin: 0;
}

.landing-assistant {
  align-items: center;
  border-top: 1px solid var(--theme-border-subtle);
  display: grid;
  gap: 1.5rem;
  grid-template-columns: auto minmax(0, 5fr) minmax(0, 6fr);
  padding: clamp(2rem, 5vw, 4rem) clamp(1rem, 4vw, 3rem);
}

.landing-assistant h2 {
  font-size: 1.25rem;
  margin: 0 0 0.5rem;
}

.landing-assistant p {
  color: var(--theme-fg-secondary);
  line-height: 1.6;
  margin: 0;
}

.landing-foot {
  align-items: center;
  border-top: 1px solid var(--theme-border-subtle);
  color: var(--theme-fg-muted);
  display: flex;
  font-size: 0.85rem;
  justify-content: space-between;
  padding: 1.25rem clamp(1rem, 4vw, 3rem);
}

@media (max-width: 860px) {
  .landing-hero,
  .landing-section,
  .landing-assistant {
    grid-template-columns: 1fr;
  }

  .landing-section--flip .landing-section__shot {
    order: 0;
  }

  .landing-hero__copy h1 {
    font-size: 1.85rem;
  }
}

* {
  box-sizing: border-box;
}
html,
body,
#root {
  min-height: 100%;
  margin: 0;
}
body {
  background: var(--theme-bg-canvas);
  color: var(--theme-text-primary);
  font-family: var(--font-sans);
  font-size: var(--type-body);
  line-height: var(--line-body);
}
button,
input {
  color: inherit;
  font: inherit;
}
button,
input,
a {
  border-radius: var(--r-2);
}
button {
  border: 1px solid var(--theme-border-subtle);
  background: var(--theme-surface-card);
  padding: 0.5rem 0.75rem;
}
button:hover,
a:hover {
  background: var(--theme-surface-hover);
}
button:focus-visible,
input:focus-visible,
a:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 2px;
}
:root[data-theme="dark"] button:focus-visible,
:root[data-theme="dark"] input:focus-visible,
:root[data-theme="dark"] a:focus-visible {
  outline-color: var(--theme-accent-strong);
}
.auth-screen {
  align-items: center;
  background: var(--theme-bg-canvas);
  display: flex;
  justify-content: center;
  min-height: 100vh;
  padding: 2rem;
}
.auth-card {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  display: grid;
  gap: 1rem;
  max-width: 28rem;
  padding: 2rem;
  width: 100%;
}
.auth-card form,
.auth-form,
.onboarding-systems,
.organization-list {
  display: grid;
  gap: 0.5rem;
}
.auth-card input {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  padding: 0.75rem;
}
.auth-card__brand {
  align-items: baseline;
  display: flex;
  gap: 0.5rem;
}
.auth-card__brand .brand-os {
  color: var(--theme-text-muted);
  font-size: var(--type-micro);
  font-weight: 600;
  letter-spacing: 0.14em;
}
.auth-card__header,
.onboarding-head {
  display: grid;
  gap: 0.25rem;
}
.auth-card__header h1 {
  font-size: var(--text-title);
  margin: 0;
}
.auth-hint,
.onboarding-sub {
  color: var(--theme-text-secondary);
  margin: 0;
}
.auth-notice {
  border-radius: var(--r-2);
  font-size: var(--type-dense);
  margin: 0;
  padding: 0.5rem 0.75rem;
}
.auth-notice--ok {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}
.auth-notice--error {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}
.auth-qr {
  align-self: center;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  max-width: 10rem;
}
.org-option,
.onboarding-system {
  align-items: center;
  display: flex;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
  text-align: left;
  width: 100%;
}
.org-option:disabled {
  cursor: wait;
  opacity: 0.7;
}
.org-option__glyph {
  align-items: center;
  background: var(--theme-accent-soft);
  border-radius: var(--r-2);
  color: var(--theme-accent-ink);
  display: inline-flex;
  font-weight: 600;
  height: 2rem;
  justify-content: center;
  width: 2rem;
}
.org-option__meta,
.onboarding-system__meta {
  display: grid;
  flex: 1;
  min-width: 0;
}
.org-option__sub {
  color: var(--theme-text-muted);
  font-size: var(--type-micro);
}
.onboarding {
  display: grid;
  gap: var(--space-4);
  margin: 0 auto;
  max-width: 46rem;
  padding: var(--space-6) var(--space-4);
}
.onboarding-head h1 {
  font-size: var(--text-display);
  margin: 0;
}
.onboarding-steps {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.onboarding-step {
  align-items: center;
  display: flex;
}
.onboarding-step:not(:last-child)::after {
  color: var(--theme-text-muted);
  content: "›";
}
.onboarding-step button {
  align-items: center;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  color: var(--theme-text-primary);
  display: flex;
  gap: 0.375rem;
  padding: 0.25rem 0.5rem;
}
.onboarding-step.is-current button {
  border-color: var(--theme-accent);
  color: var(--theme-accent-ink);
  font-weight: 600;
}
.onboarding-step.is-done button {
  color: var(--theme-success);
}
.onboarding-step.is-done .onboarding-step__index {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}
.onboarding-step__index {
  align-items: center;
  background: var(--theme-surface-card);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  display: inline-flex;
  font-size: var(--type-micro);
  font-weight: 600;
  height: 1.25rem;
  justify-content: center;
  width: 1.25rem;
}
.onboarding-panel {
  display: grid;
  gap: var(--space-3);
}
.onboarding-card {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-lg);
  display: grid;
  gap: var(--space-3);
  padding: var(--space-5);
}
.onboarding-card h2 {
  font-size: var(--type-workshop);
  margin: 0;
}
.onboarding-org {
  align-items: center;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  display: flex;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
}
.onboarding-system.is-picked,
.onboarding-choice__card.is-picked {
  border-color: var(--theme-accent);
  box-shadow: var(--e2);
}
.onboarding-choice {
  display: grid;
  gap: 0.5rem;
  grid-template-columns: 1fr 1fr;
}
.onboarding-choice__card {
  align-items: flex-start;
  display: grid;
  gap: 0.375rem;
  padding: 0.75rem;
  text-align: left;
}
.onboarding-choice__card span {
  color: var(--theme-text-secondary);
  font-size: var(--type-dense);
}
.onboarding-note {
  border-top: 1px dashed var(--theme-border-subtle);
  color: var(--theme-text-secondary);
  margin: 0;
  padding-top: var(--space-3);
}
.onboarding-link {
  justify-self: start;
}
.onboarding-actions {
  display: flex;
  gap: 0.5rem;
  justify-content: space-between;
}
.dashboard-empty__actions {
  display: flex;
  gap: 0.5rem;
}
@media (max-width: 640px) {
  .onboarding-choice {
    grid-template-columns: 1fr;
  }
}
.eyebrow {
  color: var(--theme-text-secondary);
  font-size: var(--type-micro);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.organization-list button {
  display: flex;
  justify-content: space-between;
}
.app-shell {
  background: var(--theme-bg-canvas);
