  padding: 0.5rem;
}
.settings-branding-logo {
  max-height: 3.5rem;
  max-width: 100%;
  object-fit: contain;
}
.payments-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 10px;
  margin-top: 10px;
}
.payments-form label {
  display: grid;
  gap: 4px;
  font-size: var(--text-s, 12px);
  color: var(--ink-muted);
}
.payments-form-wide {
  grid-column: 1 / -1;
}
.payments-form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 8px;
}
.payments-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 10px;
  font-size: var(--text-s, 13px);
}
.payments-table th,
.payments-table td {
  text-align: left;
  padding: 6px 8px;
  border-bottom: 1px solid var(--border, #e0deda);
}
.payments-table .num {
  text-align: right;
  font-family: var(--font-mono, monospace);
}
.payments-voided td {
  opacity: 0.55;
}
.file-input-hidden {
  display: none;
}
.file-field {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.file-field__name {
  color: var(--theme-text-secondary);
  font-size: var(--text-s, 12px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.settings-theme {
  border: 1px solid var(--theme-border-strong);
  border-radius: var(--r-2);
