  background: var(--theme-accent);
  color: var(--theme-surface-panel);
}
.settings-hint {
  color: var(--theme-text-secondary);
  margin: 0 0 0.625rem;
}
.settings-links {
  display: flex;
  gap: 1.25rem;
}
.settings-links a {
  color: var(--theme-accent);
  font-weight: 600;
  text-decoration: none;
}
.rail-toggle {
  display: none;
}
.rail-scrim {
  background: transparent;
  border: none;
  cursor: default;
  display: none;
  inset: 0;
  padding: 0;
  position: fixed;
  z-index: var(--z-popover);
}
@media (max-width: 1024px) {
  .rail-toggle {
    align-items: center;
    border: none;
    border-radius: var(--radius-md);
    display: inline-flex;
    font-size: var(--type-workshop);
    height: 32px;
    justify-content: center;
    padding: 0;
    width: 32px;
  }
  .rail-scrim {
    display: block;
    visibility: hidden;
  }
  .app-shell.rail-open .rail-scrim {
    background: rgba(15, 15, 14, 0.45);
    visibility: visible;
  }
  .app-rail {
    box-shadow: none;
    left: 0;
    position: fixed;
    top: 0;
    transform: translateX(-105%);
    transition:
      transform 0.18s ease,
      visibility 0.18s ease;
    visibility: hidden;
    z-index: var(--z-drawer);
  }
  .app-shell.rail-open .app-rail {
    box-shadow: var(--e2);
    transform: translateX(0);
    visibility: visible;
  }
}
@media (min-width: 1025px) {
  .app-shell[data-studio] .app-rail {
    align-items: stretch;
    padding-inline: 0;
    width: 4rem;
  }
  .app-shell[data-studio] .app-rail__brand {
    padding-inline: 0;
    text-align: center;
  }
  .app-shell[data-studio] .app-rail__brand .brand {
    font-size: 0;
    justify-content: center;
  }
  .app-shell[data-studio] .org-switcher,
  .app-shell[data-studio] .rail-group__title,
  .app-shell[data-studio] .app-rail__identity,
  .app-shell[data-studio] .rail-item > span {
    display: none;
  }
  .app-shell[data-studio] .rail-item {
    border-left-width: 2px;
    border-radius: var(--radius-md);
    justify-content: center;
    margin-inline: auto;
    padding-inline: 0;
    width: 2.5rem;
  }
  .app-shell[data-studio] .rail-item__icon {
    height: 18px;
    width: 18px;
  }
}
@media (max-width: 640px) {
  .app-topbar {
    gap: 0.5rem;
  }
  .ui-page-header__row {
    flex-direction: column;
    gap: var(--space-2);
  }
  .ui-page-header__actions {
    flex-wrap: wrap;
    width: 100%;
  }
  .attention-item a {
    flex-wrap: wrap;
  }
  .attention-item .attention-cta {
    margin-left: 0;
  }
  .topbar-search span {
    display: none;
  }
  .workspace {
    padding: var(--space-3) var(--space-2);
  }
  .dashboard-cards {
    grid-template-columns: 1fr;
  }
  .metric-card strong {
    font-size: var(--text-title);
  }
  .dashboard-row {
    gap: 0.125rem 0.5rem;
    grid-template-columns: minmax(0, 1fr) auto;
    padding-block: 0.625rem;
  }
  .dashboard-row-name {
    grid-column: 1;
    grid-row: 1;
  }
  .dashboard-row .status-chip {
    grid-column: 2;
    grid-row: 1;
    justify-self: end;
  }
  .dashboard-row-client {
    grid-column: 1;
    grid-row: 2;
  }
  .dashboard-row-code {
    grid-column: 2;
    grid-row: 2;
    justify-self: end;
  }
  .dashboard-activity li {
    flex-wrap: wrap;
    row-gap: 0.125rem;
  }
  .onboarding {
    padding: var(--space-4) var(--space-2);
  }
