.jobs-filter {
  min-width: 10rem;
}
.jobs-list {
  grid-column: 1 / -1;
}
.jobs-list {
  display: grid;
  gap: 0.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.job-row {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  padding: 0.625rem 0.875rem;
}
.job-row-main {
  align-items: center;
  display: flex;
  flex: 1;
  gap: 0.625rem;
  min-width: 12rem;
}
.job-row-meta {
  color: var(--theme-text-secondary);
  display: flex;
  font-size: var(--type-dense);
  gap: 0.875rem;
}
.job-row-meta time {
  font-variant-numeric: tabular-nums;
}
.job-row-error {
  color: var(--theme-danger);
