  border-color: var(--theme-accent);
}
.clients-row-name {
  font-weight: 600;
}
.clients-row-meta {
  color: var(--theme-text-secondary);
  font-size: var(--type-dense);
}
.clients-empty {
  align-items: center;
  color: var(--theme-text-secondary);
  display: flex;
  gap: 0.6rem;
  padding: 0.75rem;
}
.clients-empty__cta {
  background: transparent;
  border: 1px solid var(--theme-accent);
  border-radius: var(--radius-sm);
  color: var(--theme-accent-ink);
  font-size: var(--type-dense);
  padding: 0.18rem 0.6rem;
}
.clients-detail {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  padding: 1rem 1.25rem;
}
.clients-detail-head {
  align-items: start;
  display: flex;
  gap: 1rem;
  justify-content: space-between;
}
.clients-detail-head h2 {
  margin: 0;
}
.clients-detail-meta {
  color: var(--theme-text-secondary);
  margin: 0.25rem 0 0;
}
.clients-detail-actions {
  display: flex;
  gap: 0.5rem;
}
.clients-facts {
  display: grid;
  gap: 0.5rem;
  grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));
  margin: 1rem 0;
}
.clients-facts dt {
  color: var(--theme-text-secondary);
  font-size: var(--type-micro);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.clients-facts dd {
  margin: 0.125rem 0 0;
  white-space: pre-wrap;
}
.clients-projects {
  list-style: none;
  margin: 0.5rem 0 0;
  padding: 0;
}
.clients-project-row {
  align-items: center;
  color: var(--theme-text-primary);
  display: grid;
  gap: 0.75rem;
  grid-template-columns: auto minmax(8rem, 1fr) auto auto;
  padding: 0.5rem 0;
  text-decoration: none;
}
.clients-project-row + li {
  border-top: 1px solid var(--theme-border-subtle);
}
.clients-project-row time {
  color: var(--theme-text-secondary);
  font-size: var(--type-dense);
}
@media (max-width: 900px) {
  .clients-desk {
    grid-template-columns: 1fr;
  }
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}
label:has(> input[type="checkbox"]),
label.settings-inline {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}
label:has(> input[type="checkbox"]) input[type="checkbox"],
label.settings-inline input[type="checkbox"] {
  flex: none;
}

