  border: 0;
  background: transparent;
}
.ui-select {
  appearance: none;
  padding-right: var(--space-24px);
}
.ui-select__chevron {
  position: absolute;
  right: var(--space-8px);
  pointer-events: none;
}
.ui-check,
.ui-switch {
  display: inline-flex;
  align-items: center;
  gap: var(--space-8px);
  min-height: var(--control-height);
  cursor: pointer;
}
.ui-check input {
  accent-color: var(--interactive-fill);
  width: var(--space-16px);
  height: var(--space-16px);
}
.ui-switch {
  position: relative;
}
.ui-switch input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}
.ui-switch__track {
  width: var(--space-32px);
  height: var(--space-16px);
  border: 1px solid var(--border-strong);
  border-radius: var(--r-1);
  background: var(--surface-card);
}
.ui-switch__track::before {
  content: "";
  display: block;
  width: var(--space-12px);
  height: var(--space-12px);
  margin: 1px;
  background: var(--text-secondary);
  transition: transform var(--t-state) var(--ease-in);
}
.ui-switch input:checked + .ui-switch__track::before {
  background: var(--interactive);
  transform: translateX(16px);
}
.ui-switch input:focus-visible + .ui-switch__track {
  outline: 2px solid var(--border-focus);
  outline-offset: 1px;
}
.ui-segmented {
  display: inline-flex;
  flex-wrap: wrap;
  gap: var(--space-2px);
}
.ui-segmented [aria-checked="true"] {
  border-color: var(--interactive);
  background: var(--surface-selected);
}
.ui-combobox {
  position: relative;
}
.ui-combobox__list {
  position: absolute;
  z-index: var(--z-popover);
  top: 100%;
  width: 100%;
  max-height: 16rem;
  overflow-y: auto;
  background: var(--surface-panel);
  border: 1px solid var(--border-default);
  border-radius: var(--r-2);
  box-shadow: var(--e2);
}
.ui-combobox__option {
  display: flex;
  align-items: center;
  min-height: var(--control-height);
  padding-inline: var(--space-8px);
  cursor: pointer;
}
.ui-combobox__option[data-active],
.ui-combobox__option[aria-selected="true"] {
  background: var(--surface-selected);
}
.ui-combobox__option[aria-disabled="true"] {
  color: var(--text-disabled);
  cursor: not-allowed;
}
.ui-form-errors p {
  font-weight: 500;
}
.ui-form-errors button {
  text-align: left;
  background: none;
  border: none;
  color: inherit;
}
[data-density="workshop"] :is(button, a, input, select, textarea, summary),
[data-density="workshop"] .ui-check {
  min-height: var(--density-loose);
  min-width: var(--density-loose);
}
.ui-panel {
  padding: var(--space-12px);
  border-block-start: 1px solid var(--border-default);
}
.ui-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-8px);
  margin-block-end: var(--space-12px);
}
.ui-panel__header h2,
.ui-inspector :is(h2, h3) {
  margin: 0;
  font-size: var(--type-title-m);
  line-height: var(--line-title-m);
  font-weight: 600;
}
.ui-button-group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-8px);
}
.ui-inspector {
  width: min(100%, var(--inspector-width));
  padding: var(--space-12px);
  border-inline-start: 1px solid var(--border-default);
  background: var(--surface-panel);
}
.ui-inspector details {
  padding-block: var(--space-8px);
  border-block-end: 1px solid var(--border-subtle);
}
.ui-inspector summary {
  cursor: pointer;
  font-weight: 500;
  margin-block-end: var(--space-8px);
}
.ui-key-value {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
  gap: var(--space-8px);
  min-height: var(--density-compact);
  align-items: center;
  border-bottom: 1px solid var(--border-subtle);
}
.ui-key-value dt {
  color: var(--text-secondary);
  font-size: var(--type-label);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.ui-key-value dd {
  margin: 0;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.ui-stepper {
  display: flex;
  flex-wrap: wrap;
  list-style: none;
  gap: var(--space-8px);
  padding: 0;
}
.ui-stepper li {
  display: flex;
  align-items: center;
  gap: var(--space-8px);
  color: var(--text-secondary);
}
.ui-stepper li + li::before {
  content: "›";
}
.ui-stepper [aria-current="step"] {
  color: var(--text-primary);
  font-weight: 600;
  border-block-end: 2px solid var(--interactive);
}
.ui-stepper [data-complete]::after {
  content: "✓";
}
.ui-stat {
  display: grid;
  align-content: start;
  gap: var(--space-4px);
}
.ui-stat strong {
  font-weight: 500;
}
.ui-empty {
  display: grid;
  justify-items: center;
  gap: var(--space-8px);
  padding: var(--space-24px) var(--space-16px);
  border: 1px dashed var(--border-default);
  border-radius: var(--r-2);
  text-align: center;
}
.ui-empty__title {
  margin: 0;
  color: var(--text-primary);
  font-size: var(--type-title-l);
  font-weight: 600;
}
.ui-empty__body {
  margin: 0;
  max-width: 48ch;
  color: var(--text-secondary);
}
.ui-empty__action {
  margin-block-start: var(--space-8px);
}
.ui-empty--error,
.ui-empty--blocked {
  border-color: var(--state-danger);
}
.ui-empty--denied {
  border-style: solid;
  min-height: 12rem;
}
.ui-empty__glyph {
  width: var(--space-32px);
  height: var(--space-32px);
  fill: none;
  stroke: var(--text-secondary);
  stroke-width: 1.5;
  stroke-linecap: square;
  stroke-linejoin: miter;
}
.ui-skeleton {
  display: grid;
  gap: var(--space-8px);
  padding: var(--space-16px);
}
.ui-skeleton__line {
  display: block;
  height: var(--space-16px);
  border-radius: var(--r-1);
  background: var(--border-subtle);
}
.ui-loading-state {
  display: grid;
  gap: var(--space-8px);
}
.ui-banner {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-12px);
  padding: var(--space-12px);
  border: 1px solid var(--border-default);
  border-radius: var(--r-2);
  background: var(--surface-card);
  color: var(--text-primary);
}
.ui-banner__title {
  margin: 0;
  font-weight: 500;
}
.ui-banner__body {
  margin-block-start: var(--space-4px);
}
.ui-banner--warning {
  background: var(--state-warning-soft);
  border-color: var(--state-warning);
}
.ui-banner--danger,
.ui-banner--blocked {
  background: var(--state-danger-soft);
  border-color: var(--state-danger);
}
.ui-banner--info {
  background: var(--state-info-soft);
  border-color: var(--state-info);
}
.ui-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-4px);
  padding: var(--space-2px) var(--space-4px);
  border: 1px solid transparent;
  border-radius: var(--r-1);
  color: var(--text-secondary);
  background: var(--surface-card);
  font-size: var(--type-dense);
  font-weight: 500;
}
.ui-badge--success {
  color: var(--state-success-ink);
  background: var(--state-success-soft);
}
.ui-badge--warning {
  color: var(--state-warning-ink);
  background: var(--state-warning-soft);
}
.ui-badge--danger,
.ui-badge--blocked {
  color: var(--state-danger-ink);
  background: var(--state-danger-soft);
}
.ui-badge--info {
  color: var(--state-info-ink);
  background: var(--state-info-soft);
}
.ui-evidence {
  display: inline-flex;
  padding: var(--space-2px) var(--space-4px);
  border: 1px solid var(--border-default);
  border-radius: var(--r-1);
  color: var(--text-secondary);
  font: var(--type-dense) / var(--line-dense) var(--font-mono);
}
.ui-overlay {
  position: fixed;
  inset: 0;
  z-index: var(--z-dialog);
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--scrim);
}
.ui-dialog {
  display: flex;
  flex-direction: column;
  width: 34rem;
  max-width: calc(100vw - 2rem);
  max-height: 85vh;
  border: 1px solid var(--border-default);
  border-radius: var(--r-2);
  background: var(--surface-panel);
  color: var(--text-primary);
  box-shadow: var(--e3);
}
.ui-dialog--s {
  width: 24rem;
}
.ui-dialog--l {
  width: 48rem;
}
.ui-dialog__header,
.ui-dialog__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-8px);
  padding: var(--space-12px) var(--space-16px);
}
.ui-dialog__header {
  border-bottom: 1px solid var(--border-subtle);
}
.ui-dialog__footer {
  justify-content: flex-end;
  border-top: 1px solid var(--border-subtle);
}
.ui-dialog__title {
  margin: 0;
  font-size: var(--type-title-l);
  line-height: var(--line-title-l);
  font-weight: 600;
}
.ui-dialog__body {
  padding: var(--space-16px);
  overflow-y: auto;
}
.ui-dialog__text {
  margin: 0;
  color: var(--text-secondary);
}
.ui-overlay--drawer {
  justify-content: flex-end;
  z-index: var(--z-drawer);
}
.ui-dialog--drawer {
  height: 100%;
  max-height: 100%;
  width: min(100%, 32rem);
  max-width: 100%;
  border-radius: var(--r-0);
}
.ui-overlay--palette {
  z-index: var(--z-palette);
  align-items: flex-start;
  padding-top: 16vh;
}
.ui-popover-anchor,
.ui-tooltip-anchor {
  display: inline-flex;
  position: relative;
}
.ui-popover,
.ui-tooltip,
.ui-context-menu {
  z-index: var(--z-popover);
  padding: var(--space-8px);
  border: 1px solid var(--border-default);
  border-radius: var(--r-2);
  background: var(--surface-panel);
  color: var(--text-primary);
  box-shadow: var(--e2);
}
.ui-popover,
.ui-tooltip {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  width: max-content;
  max-width: min(28rem, calc(100vw - 2rem));
  max-height: calc(100dvh - var(--space-16px));
  overflow: auto;
}
.ui-tooltip {
  font-size: var(--type-dense);
  pointer-events: none;
}
.ui-context-menu {
  position: fixed;
  width: 16rem;
}
.ui-menu,
.ui-command-list {
  display: grid;
}
.ui-menu__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-16px);
  min-height: var(--control-height);
  width: 100%;
  padding: var(--space-4px) var(--space-8px);
  background: transparent;
  border: 0;
  border-radius: var(--r-1);
  color: var(--text-primary);
  text-decoration: none;
}
.ui-menu__item:hover,
.ui-command-list [aria-selected="true"] {
  background: var(--surface-selected);
}
.ui-menu__item.is-danger {
  color: var(--state-danger-ink);
}
.ui-command-help,
kbd {
  font: var(--type-dense) / var(--line-dense) var(--font-mono);
  color: var(--text-secondary);
}
.ui-toast-region {
  position: fixed;
  right: var(--space-16px);
  bottom: var(--space-16px);
  z-index: var(--z-toast);
  display: grid;
  gap: var(--space-8px);
}
.ui-toast {
  max-width: 22rem;
  padding: var(--space-8px) var(--space-12px);
  background: var(--surface-panel);
  border: 1px solid var(--border-default);
  border-inline-start: 2px solid var(--state-success);
  border-radius: var(--r-1);
  color: var(--text-primary);
}
.ui-toast--info {
  border-inline-start-color: var(--interactive);
}
.ui-sheet {
  padding: var(--space-16px);
  border: 1px solid var(--border-default);
  background: var(--surface-sheet);
  box-shadow: var(--sheet);
}
.ui-value {
  font-family: var(--font-mono);
  font-size: var(--type-dim);
  font-variant-numeric: tabular-nums;
  line-height: var(--line-dim);
}
.ui-value__unit {
  font-size: max(0.85em, var(--type-micro));
  color: var(--text-small-muted);
}
.ui-code {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-4px);
}
.ui-code__button {
  background: transparent;
  border: 1px solid transparent;
  padding: var(--space-2px);
  color: var(--interactive);
}
.ui-code__fallback {
  display: grid;
  gap: var(--space-4px);
}
.ui-unknown,
.ui-unknown__cause {
  color: var(--text-secondary);
}
.ui-unknown__action {
  margin-inline-start: var(--space-8px);
}
.ui-demo {
  padding: var(--space-2px) var(--space-4px);
  border: 1px dashed var(--border-strong);
  border-radius: var(--r-1);
  color: var(--text-secondary);
  font: 500 var(--type-label) / var(--line-label) var(--font-mono);
}
.ui-dim-loader {
  display: inline-flex;
  width: var(--space-64px);
  color: var(--interactive);
}
.ui-button .ui-dim-loader {
  width: var(--space-24px);
  color: inherit;
}
.ui-dim-loader svg {
  width: 100%;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: square;
}
.ui-dim-loader__measure {
  transition: stroke-dashoffset var(--t-state) linear;
}
.ui-glyph,
.ui-opening-glyph {
  flex: 0 0 auto;
  width: var(--space-24px);
  height: var(--space-24px);
}
.ui-badge .ui-glyph {
  width: var(--space-12px);
  height: var(--space-12px);
}
.ui-trace dl,
.ui-trace dl > div {
  display: grid;
  gap: var(--space-4px);
}
.ui-trace dl > div {
  grid-template-columns: 1fr 1fr;
}
.ui-trace dd {
  margin: 0;
  font-family: var(--font-mono);
  overflow-wrap: anywhere;
}
.ui-trace__formula {
  font-family: var(--font-mono);
  white-space: pre-wrap;
}
.ui-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  clip-path: inset(50%);
  overflow: hidden;
  white-space: nowrap;
}
.ui-table-region {
  display: grid;
  gap: var(--space-8px);
  min-width: 0;
}
.ui-table-scroll {
  overflow: auto;
  max-width: 100%;
  max-height: 28rem;
}
.ui-table-scroll.is-virtual {
  max-height: 28rem;
  overflow-anchor: none;
}
.ui-data-table,
.ui-table {
  width: 100%;
  border-collapse: collapse;
}
.ui-data-table :is(th, td) {
  height: var(--table-row-height);
  border-bottom: 1px solid var(--border-subtle);
  padding: 0 var(--space-8px);
  text-align: left;
}
.ui-data-table th {
  position: sticky;
  top: 0;
  z-index: var(--z-sticky);
  background: var(--surface-panel);
  color: var(--text-secondary);
  font-size: var(--type-label);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.ui-data-table th button {
  border: 0;
  background: transparent;
  font: inherit;
  color: inherit;
  padding: 0;
  height: var(--control-height);
}
.ui-data-table .is-numeric {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.ui-data-table tr[data-selected] {
  background: var(--surface-selected);
  border-inline-start: 2px solid var(--interactive);
}
.ui-data-table tr:hover {
  background: var(--surface-hover);
}
.ui-table-selection {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-8px);
  padding: var(--space-4px);
  border-block: 1px solid var(--border-default);
}
.is-virtual .ui-data-table td {
  white-space: nowrap;
  max-width: 24rem;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* §15 profile section preview — true-scale cross-section with provenance. */
.section-preview {
  margin: 0;
  display: grid;
  gap: 0.35rem;
}

.section-preview svg {
  display: block;
  width: 100%;
  max-width: 180px;
  height: auto;
  border: 1px solid var(--line, #d8d8d8);
  border-radius: var(--radius-sm);
  background: var(--surface-raised, #fff);
}

.section-preview__shape {
  stroke-width: 0.6;
  vector-effect: non-scaling-stroke;
}

.section-preview__shape--approx {
  fill: none;
  stroke-dasharray: 3 2;
}

.section-preview__axis {
  stroke: var(--line-strong, #9a9a9a);
  stroke-width: 0.4;
  stroke-dasharray: 4 2;
  vector-effect: non-scaling-stroke;
}

.section-preview__axis-label,
.section-preview__dims {
  fill: var(--ink-3, #6b6b6b);
  font-family: var(--font-mono, monospace);
}

.section-preview figcaption {
  display: grid;
  gap: var(--space-1);
  font-size: var(--type-dense);
  color: var(--ink-3, #6b6b6b);
}

.section-preview[data-provenance="APPROXIMATE"] figcaption::before {
  content: "◌ ";
}

.section-preview[data-provenance="POLYGON"] figcaption::before,
.section-preview[data-provenance="DXF_REFERENCE"] figcaption::before {
  content: "■ ";
}

.section-preview-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.catalog {
  color: var(--theme-text-primary);
  background: var(--theme-bg-canvas);
  font-size: 0.875rem;
}

.catalog h1,
.catalog h2,
.catalog h3,
.catalog p {
  margin: 0;
}

.catalog h1 {
  font-size: var(--text-display);
}
.catalog h2 {
  font-size: var(--text-title);
}
.catalog h3 {
  font-size: 0.95rem;
}

.catalog p,
.catalog small {
  color: var(--theme-text-secondary);
  line-height: 1.5;
}
.catalog-layout[hidden] {
  display: none;
}
.catalog-review-field > div,
.catalog-diff-values > div > * {
  min-width: 0;
}

.catalog-heading,
.catalog-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.catalog-heading > div,
.catalog-detail > header {
  display: grid;
  gap: 0.35rem;
}

.catalog-status {
  min-height: 1.75rem;
}
.catalog-loading {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.catalog-layout {
  display: grid;
  grid-template-columns: minmax(13rem, 17rem) minmax(0, 1fr);
  gap: 1rem;
  align-items: start;
}

.catalog-master,
.catalog-detail {
  min-width: 0;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  background: var(--theme-surface-panel);
  padding: 0.875rem;
}

.catalog-master {
  display: grid;
  gap: 0.75rem;
}

.catalog-master ul {
  display: grid;
  gap: 0.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.catalog .catalog-system {
  display: grid;
  width: 100%;
  gap: 0.2rem;
  text-align: left;
  padding: 0.65rem;
}

.catalog-system span {
  color: var(--theme-text-secondary);
}

.catalog-detail {
  display: grid;
  gap: 1rem;
}

/* Long system names/records must wrap, not stretch the page — the detail
 * column hosts wide tables inside scroll containers, which can only shrink
 * if every level allows min-width:0. */
.catalog-detail > *,
.ws > * {
  min-width: 0;
}
.catalog-detail h2,
.ws-identity-head h2,
.ws-chip,
.ws-badge {
  overflow-wrap: anywhere;
}

.catalog-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--theme-border-subtle);
}

.catalog button,
.catalog input,
.catalog select {
  font: inherit;
  color: var(--theme-text-primary);
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-1);
  min-height: 2.25rem;
}

.catalog button {
  padding: 0.4rem 0.7rem;
  cursor: pointer;
}

.catalog button:hover:not(:disabled) {
  background: var(--theme-surface-hover);
}
.catalog .ui-button--primary:not(:disabled) {
  color: var(--text-on-fill);
  background: var(--interactive-fill);
  border-color: var(--interactive-fill);
}

.catalog button[aria-current="true"],
.catalog button[aria-pressed="true"] {
  border-color: var(--theme-accent);
  background: var(--theme-surface-card);
  outline: 1px solid var(--interactive);
  outline-offset: -1px;
}

.catalog button:disabled,
.catalog fieldset:disabled {
  cursor: default;
  opacity: 0.65;
}

.catalog :focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 3px;
}

.catalog label {
  display: grid;
  align-content: start;
  gap: 0.3rem;
  min-width: 0;
}

.catalog input,
.catalog select {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 0.4rem 0.5rem;
}

.catalog input[type="checkbox"] {
  width: var(--space-16px);
  height: var(--space-16px);
  min-height: var(--space-16px);
  margin: 0;
  padding: 0;
  accent-color: var(--interactive-fill);
}
.catalog label:has(> input[type="checkbox"]) {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-height: var(--control-height);
  max-width: 100%;
  margin-inline-end: var(--space-3);
  vertical-align: middle;
}
.catalog label:has(> input[type="checkbox"]) > input {
  flex: 0 0 var(--space-16px);
}
.catalog input[inputmode="decimal"] {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.catalog-table-scroll {
  overflow-x: auto;
}

.catalog table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

.catalog th,
.catalog td {
  padding: 0.55rem;
  border-bottom: 1px solid var(--theme-border-subtle);
  vertical-align: middle;
}

.catalog thead {
  color: var(--theme-text-secondary);
  background: var(--theme-surface-card);
}

.catalog tbody th {
  font-weight: 500;
}

.catalog-empty {
  padding: 1.5rem 0.75rem;
  border: 1px dashed var(--theme-border-subtle);
}

.catalog-editor {
  display: grid;
  gap: 0.875rem;
  padding-top: 1rem;
  border-top: 2px solid var(--theme-accent);
}

.catalog-controls {
  display: grid;
  gap: 1rem;
  min-width: 0;
  border: 0;
  padding: 0;
  margin: 0;
}

.catalog-group {
  min-width: 0;
  margin: 0;
  padding: 0.75rem;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--theme-radius-sm);
}

.catalog-group legend {
  padding: 0 0.35rem;
  font-weight: 600;
}

.catalog-fields {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 0.75rem;
}

.catalog-field-hint {
  display: block;
  margin-top: 0.25rem;
}

.catalog-contents {
  min-width: 39rem;
}
.catalog-contents td:nth-child(2) {
  width: 35%;
}

.catalog .catalog-primary {
  border-color: var(--theme-success);
}

.catalog .catalog-danger,
.catalog [role="alert"] {
  color: var(--theme-danger);
}

.catalog-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 760px) {
  .catalog {
    padding: 0.625rem;
  }
  .catalog-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .catalog-master ul {
    max-height: 14rem;
    overflow-y: auto;
  }
}

/* §06 system workspace */
.ws {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}
.ws-identity {
  border: 1px solid var(--theme-border);
  border-radius: var(--theme-radius);
  padding: 1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.ws-identity-head {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
.ws-identity-head h2 {
  margin: 0;
  font-size: 1.15rem;
  display: flex;
  gap: 0.6rem;
  align-items: baseline;
  flex-wrap: wrap;
}
.ws-identity-head h2 code {
  font-size: 0.85rem;
  color: var(--theme-text-dim);
}
.ws-identity-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}
.ws-chip {
  font-size: 0.75rem;
  padding: 0.15rem 0.55rem;
  border-radius: var(--theme-radius-pill);
  background: var(--theme-surface-2, rgba(0, 0, 0, 0.06));
}
.ws-chip--off {
  border: 1px solid var(--theme-warning, #b26a00);
  color: var(--theme-warning, #b26a00);
  background: transparent;
}
.ws-centers {
  margin-top: 0.9rem;
}
.ws-centers h4 {
  margin: 0 0 0.3rem;
}
.ws-center-form {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
  margin-top: 0.55rem;
}
.ws-center-form input {
  background: var(--theme-surface);
  border: 1px solid var(--theme-border);
  border-radius: var(--r-1);
  padding: 0.42rem 0.6rem;
  font: inherit;
  min-width: 8rem;
}
.ws-center-form input:first-of-type {
  min-width: 5rem;
  width: 7rem;
  text-transform: uppercase;
}
.ws-center-form select {
  background: var(--theme-surface);
  border: 1px solid var(--theme-border);
  border-radius: var(--r-1);
  padding: 0.42rem 0.5rem;
  font: inherit;
}
.ws-center-form [role="alert"] {
  color: var(--theme-danger, #b3261e);
  font-size: 0.82rem;
}
.ws-badge {
  font-size: 0.72rem;
  padding: 0.15rem 0.55rem;
  border-radius: var(--r-1);
  border: 1px solid var(--theme-border);
}
.ws-badge--ok {
  border-color: var(--theme-ok, #2e7d32);
  color: var(--theme-ok, #2e7d32);
}
.ws-badge--warn {
  border-color: var(--theme-warn, #b26a00);
  color: var(--theme-warn, #b26a00);
}
.ws-identity-facts {
  display: flex;
  gap: 2rem;
  flex-wrap: wrap;
  margin: 0;
}
.ws-identity-facts div {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}
.ws-identity-facts dt {
  font-size: 0.72rem;
  color: var(--theme-text-dim);
}
.ws-identity-facts dd {
  margin: 0;
  font-weight: 600;
}
.ws-ladder {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 0.6rem;
}
.ws-ladder-level {
  border: 1px solid var(--theme-border);
  border-radius: var(--theme-radius);
  padding: 0.6rem 0.75rem;
}
.ws-ladder-level.is-ok {
  border-color: var(--theme-ok, #2e7d32);
}
.ws-ladder-level.is-blocked {
  border-color: var(--theme-warn, #b26a00);
}
.ws-ladder-level header {
  display: flex;
  gap: 0.4rem;
  align-items: baseline;
}
.ws-ladder-state {
  font-size: 0.8rem;
}
.ws-ladder-level.is-ok .ws-ladder-state {
  color: var(--theme-ok, #2e7d32);
}
.ws-ladder-level.is-blocked .ws-ladder-state {
  color: var(--theme-warn, #b26a00);
}
.ws-ladder-level em {
  margin-left: auto;
  font-size: 0.7rem;
  font-style: normal;
  color: var(--theme-text-dim);
}
.ws-blockers {
  list-style: none;
  margin: 0.6rem 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}
.ws-blocker {
  background: var(--theme-surface-raised, var(--theme-surface));
  border: 1px solid var(--theme-border);
  border-radius: var(--theme-radius);
  padding: 0.5rem 0.7rem;
}
.ws-blocker-head {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.ws-blocker-level {
  background: var(--theme-warn-bg, #fdf3e3);
  border-radius: var(--r-1);
  color: var(--theme-warn, #b26a00);
  font-size: var(--type-dense);
  font-weight: 600;
  padding: 0.1rem 0.45rem;
  text-transform: uppercase;
}
.ws-blocker-target {
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  color: var(--theme-text);
}
.ws-blocker-target:hover {
  text-decoration: underline;
}
.ws-blocker-affected {
  color: var(--theme-text-dim);
  font-size: 0.85rem;
}
.ws-blocker-detail {
  margin: 0.3rem 0 0;
  font-size: 0.78rem;
  color: var(--theme-text-dim);
  line-height: 1.45;
}
.ws-map {
  border: 1px solid var(--theme-border);
  border-radius: var(--theme-radius);
  padding: 0.85rem 1rem;
}
.ws-map h3 {
  margin: 0 0 0.6rem;
  font-size: 0.95rem;
}
.ws-map-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}
.ws-map-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.ws-map-edge {
  color: var(--theme-text-dim);
}
.ws-map-node {
  border: 1px solid var(--theme-border);
  border-radius: var(--theme-radius);
  background: var(--theme-surface);
  padding: 0.45rem 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  font: inherit;
  cursor: pointer;
  text-align: left;
}
.ws-map-node small {
  color: var(--theme-text-dim);
}
.ws-map-node.is-active {
  border-color: var(--theme-accent);
  outline: 2px solid var(--theme-accent-soft, rgba(0, 0, 0, 0.1));
}
.ws-map-detail {
  margin-top: 0.75rem;
  border-top: 1px dashed var(--theme-border);
  padding-top: 0.6rem;
  font-size: 0.85rem;
}
.ws-map-detail p {
  margin: 0.2rem 0;
}
.ws-section {
  border-top: 1px solid var(--theme-border);
  padding-top: 0.9rem;
}
.ws-section-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.6rem;
}
.ws-section-head h3 {
  margin: 0;
  font-size: 0.95rem;
}
.ws-count {
  color: var(--theme-text-dim);
  font-weight: 400;
  font-size: 0.85rem;
  margin-left: 0.35rem;
}
.ws-empty {
  color: var(--theme-text-dim);
  font-size: 0.85rem;
}
.ws-article-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 0.75rem;
}
.ws-article-card {
  border: 1px solid var(--theme-border);
  border-radius: var(--theme-radius);
  padding: 0.6rem;
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  gap: 0.7rem;
}
.ws-article-section {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  align-items: center;
}
.ws-article-section svg {
  width: 88px;
  height: 88px;
}
.ws-article-section small {
  font-size: var(--type-dense);
  color: var(--theme-text-dim);
  text-align: center;
}
.ws-article-body header {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  margin-bottom: 0.4rem;
}
.ws-article-body header code {
  font-size: 0.75rem;
  color: var(--theme-text-dim);
}
.ws-article-body dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.3rem 0.75rem;
  margin: 0 0 0.5rem;
  font-size: 0.78rem;
}
.ws-article-body dl div {
  display: flex;
  flex-direction: column;
}
.ws-article-body dt {
  color: var(--theme-text-dim);
  font-size: var(--type-dense);
}
.ws-article-body dd {
  margin: 0;
}
.ws-article-body footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
}
.ws-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}
.ws-table th,
.ws-table td {
  text-align: left;
  padding: 0.4rem 0.6rem;
  border-bottom: 1px solid var(--theme-border);
}
.ws-table thead th {
  font-size: 0.72rem;
  color: var(--theme-text-dim);
  font-weight: 500;
}
.ws-kit-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}
.ws-kit-card {
  border: 1px solid var(--theme-border);
  border-radius: var(--theme-radius);
  background: var(--theme-surface);
  padding: 0.6rem 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  font: inherit;
  cursor: pointer;
  text-align: left;
  min-width: 160px;
}
.ws-kit-card span {
  font-size: 0.75rem;
  color: var(--theme-text-dim);
}
.ws-kit-card small {
  font-size: 0.75rem;
}
.ws-process header {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin-bottom: 0.75rem;
}
.ws-process-cols {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
}
.ws-process-cols h4 {
  margin: 0 0 0.4rem;
  font-size: 0.8rem;
  color: var(--theme-text-dim);
  font-weight: 500;
}
.ws-stations {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  font-size: 0.85rem;
}
.ws-stations li.ws-off {
  color: var(--theme-text-dim);
}
.ws-delete {
  border-top: 1px dashed var(--theme-border);
  padding-top: 0.75rem;
  margin: 0;
  text-align: right;
}

@media (max-width: 900px) {
  .ws-article-card {
    grid-template-columns: 1fr;
  }
}

/* §06-G section drawing import */
.section-import {
  border: 1px solid var(--theme-border);
  border-radius: var(--r-2);
  padding: 0.75rem;
  margin: 0.5rem 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.section-import-warnings {
  margin: 0;
  padding-left: 1.2rem;
  color: var(--theme-warn, #9a6700);
  font-size: 0.85rem;
}
.section-import-candidates {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.section-import-candidate {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  width: 96px;
  padding: 0.4rem;
  border: 1px solid var(--theme-border);
  border-radius: var(--r-2);
  background: transparent;
  color: var(--theme-text);
  cursor: pointer;
}
.section-import-candidate[aria-pressed="true"] {
  border-color: var(--theme-accent);
  background: var(--theme-accent-soft, rgba(60, 90, 200, 0.08));
}
.section-import-candidate svg {
  width: 72px;
  height: 72px;
  display: block;
}
.section-import-confirm {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  max-width: 320px;
}
.section-import-preview svg {
  width: 140px;
  height: 140px;
  display: block;
}
.catalog-ingest {
  margin-block: var(--space-4);
  padding: var(--space-4);
  border: 1px solid var(--border-default);
  background: var(--surface-panel);
}
.catalog-ingest h3,
.catalog-ingest h4 {
  margin: 0;
}
.catalog-ingest p {
  margin-block: var(--space-2);
}
.catalog-ingest-methods {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-4);
  margin-block: var(--space-4);
}
.catalog-ingest-methods > div {
  border-top: 2px solid var(--border-strong);
  padding-top: var(--space-3);
}
.catalog-ingest label {
  display: grid;
  gap: var(--space-1);
}
.catalog-ingest textarea,
.catalog-ingest input:not([type="checkbox"]),
.catalog-ingest select {
  width: 100%;
  min-width: 0;
}
.catalog-dropzone {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-3);
  border: 1px dashed var(--border-strong);
  padding: var(--space-3);
}
.catalog-dropzone.is-dragging {
  border-color: var(--interactive);
  background: var(--surface-selected);
}
.catalog-ingest-message {
  border-left: 2px solid var(--state-person);
  padding-inline: var(--space-3);
}
.catalog-import-entry {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  padding-block: var(--space-3);
  border-top: 1px solid var(--border-default);
}
.catalog-import-entry > div:first-child {
  display: grid;
  gap: var(--space-1);
  min-width: 0;
  overflow-wrap: anywhere;
}
.catalog-import-entry time {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}
.catalog-sheet-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-block: var(--space-3);
}
.catalog-sheet-tabs [aria-pressed="true"],
.catalog-review-rows .is-selected {
  outline: 1px solid var(--interactive);
  background: var(--surface-selected);
}
.catalog-review-layout {
  display: grid;
  grid-template-columns: 180px minmax(0, 1fr);
  gap: var(--space-3);
  align-items: start;
  margin-bottom: var(--space-3);
}
.catalog-review-rows > div {
  display: flex;
  align-items: center;
  border-bottom: 1px solid var(--border-default);
}
.catalog-review-rows button {
  display: grid;
  gap: var(--space-1);
  text-align: left;
  width: 100%;
  border: 0;
  background: transparent;
}
.catalog-review-rows span {
  font-size: var(--text-xs);
}
.catalog-review-fields {
  min-width: 0;
  border: 1px solid var(--border-default);
  padding: var(--space-2);
  margin: 0;
}
.catalog-review-heading,
.catalog-review-field {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) minmax(130px, 1fr) minmax(160px, 1.3fr);
  gap: var(--space-2);
}
.catalog-review-heading {
  font-weight: 600;
  border-bottom: 1px solid var(--border-strong);
  padding: var(--space-2);
}
.catalog-review-field {
  align-items: start;
  border-bottom: 1px solid var(--border-default);
  padding-block: var(--space-2);
}
.catalog-review-field label small {
  font-size: var(--text-xs);
  color: var(--text-muted);
}
.catalog-review-field input {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.catalog-source {
  overflow-wrap: anywhere;
  font-size: var(--text-xs);
  color: var(--text-muted);
}
.catalog-source blockquote {
  margin: var(--space-1) 0;
  color: var(--text-primary);
  white-space: pre-wrap;
}
.catalog-source strong {
  display: block;
  font-weight: 500;
  color: var(--text-primary);
}
.catalog-field-error {
  color: var(--state-danger);
  font-size: var(--text-xs);
}
.catalog-review-diff {
  margin-top: var(--space-4);
  border-top: 1px solid var(--border-strong);
  padding-top: var(--space-3);
}
.catalog-review-diff details {
  margin-block: var(--space-2);
}
.catalog-diff-values > div {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: var(--space-3);
  padding-block: var(--space-1);
  border-bottom: 1px solid var(--border-default);
}
.catalog-diff-values del,
.catalog-diff-values ins {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.catalog-diff-values ins {
  text-decoration: none;
}
.catalog-review-attestation {
  display: flex !important;
  align-items: center;
  gap: var(--space-2);
  margin-block: var(--space-3);
}
.catalog .catalog-review-attestation input[type="checkbox"] {
  flex: 0 0 auto;
  width: 18px;
  min-height: 18px;
  padding: 0;
  accent-color: var(--interactive);
}
.catalog-review-attestation span {
  min-width: 0;
}
.catalog-components > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--space-1);
  border-bottom: 1px solid var(--border-default);
  padding-bottom: var(--space-2);
}
@media (max-width: 1100px) {
  .catalog-review-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .catalog-review-rows {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
  }
}
@media (max-width: 700px) {
  .catalog-ingest-methods {
    grid-template-columns: minmax(0, 1fr);
  }
  .catalog-review-heading {
    display: none;
  }
  .catalog-review-field {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .catalog-source {
    grid-column: 1 / -1;
  }
  .catalog-import-entry {
    flex-direction: column;
  }
}
.ws-technical-code {
  min-width: 0;
  max-width: 100%;
}
.ws-technical-code summary {
  cursor: pointer;
  min-height: var(--control-height);
  color: var(--theme-accent-ink);
}
.ws-technical-code code {
  display: block;
  overflow-wrap: anywhere;
  font-family: var(--font-mono);
  font-size: var(--type-dense);
}
